<template lang='pug' src='./smilechoice.pug'></template>

<script>
import Loader from 'components/loader/loader'
import Header from 'components/header/header'
import Footer from 'components/footer/footer'

export default {
  name: 'Smile Choice',
  computed: {
    props () {
      return this.$store.state.pages['smilechoice']
    },
    propspageheader () {
      return this.$store.state.app['header']
    },
    loading () {
      return this.$store.state.loading
    }
  },
  components: {
    Loader,
    Header,
    Footer
  }
}
</script>

<style lang="sass" src="./smilechoice.sass"></style>



